#!/usr/bin/env bash
# atlas-commerce step verifier (generated by scripts/atlas/compile_atlas.py; AUTHORING.md "Verifier").
#
# Runs in main after the agent's turn, against the live platform. By then the guard (PID 1,
# environment/platform/guard.py) has killed everything the agent left running, when Harbor reset
# /logs/verifier and before /tests was uploaded. This script then:
#   1. writes a provisional reward (0, error), sweeps processes again, and notes any file in
#      /logs/verifier it did not write (a planted verdict: tampered, reward 0);
#   2. rebuilds the step's trusted start tree (base tarball checked against the manifest +
#      state.patch), copies the agent's tree, saves segment.patch, makes the copy gradeable;
#   3. gets a grader-only AWS key from the controller with this step's verify token;
#   4. runs the ticket's run.sh with results going to a root-only directory, under a deadline;
#   5. sweeps again, revokes the grader key;
#   6. takes the verdict from run.sh's exit code AND its JUnit reports (verdict.py); a
#      disagreement, or any foreign file in /logs/verifier, is tampering: reward 0;
#   7. writes details, timings and grade.json, then reward.json last.
# reward.json = {"reward": 0|1, "error": 0|1, "tampered": 0|1}; error = the grader itself failed.
set -uo pipefail

# --- compile-time values -----------------------------------------------------
@@CONFIG@@

: "${ODYSSEY_BASE_TARBALL:=/opt/odyssey/base.tar.gz}"
: "${ODYSSEY_VERIFIER_DIR:=/logs/verifier}"
: "${ODYSSEY_STOP_AGENTS:=1}"
: "${ODYSSEY_SWEEP_MATCH:=}"
: "${ATLAS_CTL_DIR:=/run/atlas-ctl}"
: "${ATLAS_GRADER_ROOT:=/var/lib/atlas-grader}"
: "${ATLAS_GRADER_PYTHON:=/opt/atlas-grader/bin/python}"
: "${ATLAS_GUARD_LOG:=/run/atlas-guard/sweeps.jsonl}"

TESTS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TICKET_DIR="$TESTS_DIR/ticket"
START_DIR="$TESTS_DIR/start"
LIB_DIR="$TESTS_DIR/atlas"
OUT="$ODYSSEY_VERIFIER_DIR"
WORK="$ATLAS_GRADER_ROOT/step-$ODYSSEY_POSITION"
TRUSTED="$WORK/trusted"
GRADE="$WORK/tree"
RESULTS="$WORK/results"
CREDS="$WORK/credentials"
PY="$ATLAS_GRADER_PYTHON"

REWARD=0
ERROR=""
TAMPERED=0
TAMPER_REASONS=()
EXIT_CODE=-1
TIMED_OUT=false
PATCH_STATUS="not attempted"
VERDICT_REASON=""
CREDS_ISSUED=0

export GIT_AUTHOR_NAME=grader GIT_AUTHOR_EMAIL=grader@localhost
export GIT_COMMITTER_NAME=grader GIT_COMMITTER_EMAIL=grader@localhost
export GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null

log() { printf '[atlas grade %s] %s\n' "$ODYSSEY_STEP" "$*" >&2; }

git_() {
    git -c safe.directory='*' -c core.hooksPath=/dev/null -c core.fsmonitor=false \
        -c commit.gpgsign=false "$@"
}

write_reward() {
    local error_flag=0
    [ -z "$ERROR" ] || error_flag=1
    printf '{"reward": %s, "error": %s, "tampered": %s}\n' "$REWARD" "$error_flag" "$TAMPERED" > "$OUT/.reward.json.tmp" \
        && mv -f "$OUT/.reward.json.tmp" "$OUT/reward.json"
}

cleanup() {
    rm -rf "$WORK"
}
trap cleanup EXIT

@@INCLUDE lib_sweep.sh@@

@@INCLUDE lib_manifest.sh@@

@@INCLUDE lib_ctl.sh@@

# Everything in /logs/verifier that this script did not write. Harbor emptied the directory
# before uploading the tests and only test-stdout.txt (its redirect) belongs there.
foreign_outputs() {
    find "$OUT" -mindepth 1 -maxdepth 1 ! -name test-stdout.txt ! -name reward.json ! -name .reward.json.tmp \
        ! -name grade.json ! -name details.json ! -name segment.patch ! -name atlas-step.json \
        ! -name guard-sweeps.jsonl ! -name grader -printf '%f\n' 2>/dev/null
}

check_planted() {
    local stage="$1" planted
    planted="$(foreign_outputs | tr '\n' ' ')"
    if [ -n "$planted" ]; then
        TAMPERED=1
        TAMPER_REASONS+=("$stage: files in $OUT not written by the grader: $planted")
        find "$OUT" -mindepth 1 -maxdepth 1 ! -name test-stdout.txt ! -name reward.json \
            ! -name grade.json ! -name details.json ! -name segment.patch ! -name atlas-step.json \
            ! -name guard-sweeps.jsonl ! -name grader -exec rm -rf {} + 2>/dev/null
    fi
    if [ -f "$OUT/reward.json" ] && ! grep -q "\"tampered\": " "$OUT/reward.json"; then
        TAMPERED=1
        TAMPER_REASONS+=("$stage: reward.json was rewritten by something else")
    fi
}

prepare_trusted() {
    mkdir -p "$TRUSTED" || { ERROR="cannot create scratch dir"; return 1; }
    [ -f "$ODYSSEY_BASE_TARBALL" ] || { ERROR="base snapshot $ODYSSEY_BASE_TARBALL missing"; return 1; }
    tar -xzf "$ODYSSEY_BASE_TARBALL" -C "$TRUSTED" || { ERROR="cannot extract the base snapshot"; return 1; }
    if [ -f "$START_DIR/base.manifest" ]; then
        tree_manifest "$TRUSTED" | cmp -s - "$START_DIR/base.manifest" \
            || { ERROR="base snapshot does not match the compiled manifest"; return 1; }
    fi
    if [ -s "$START_DIR/state.patch" ]; then
        (cd "$TRUSTED" && GIT_CEILING_DIRECTORIES="$WORK" git_ apply --whitespace=nowarn "$START_DIR/state.patch") \
            || { ERROR="state.patch does not apply to the base snapshot"; return 1; }
    fi
}

copy_agent_tree() {
    mkdir -p "$GRADE" || { ERROR="cannot create scratch dir"; return 1; }
    (cd "$ODYSSEY_WORKDIR" && tar --exclude=./.git --exclude=.git -cf - .) | (cd "$GRADE" && tar -xf -) \
        || { ERROR="copying the working tree failed"; return 1; }
}

snapshot_repo() {
    local repo="$1" tree="$2" t c
    rm -rf "$repo"
    git_ init -q --bare "$repo" || return 1
    (
        cd "$tree" &&
            GIT_INDEX_FILE="$WORK/snapshot.index" git_ --git-dir="$repo" --work-tree=. add -A &&
            t="$(GIT_INDEX_FILE="$WORK/snapshot.index" git_ --git-dir="$repo" write-tree)" &&
            c="$(git_ --git-dir="$repo" commit-tree "$t" -m start)" &&
            git_ --git-dir="$repo" update-ref HEAD "$c"
    )
}

write_segment_patch() {
    local repo="$WORK/start.git" f
    local -a pathspec=(.)
    while IFS= read -r f; do
        [ -n "$f" ] && pathspec+=(":(exclude,literal,top)$f")
    done <<EOF
$ODYSSEY_MEMORY_FILES
EOF
    snapshot_repo "$repo" "$TRUSTED" || { PATCH_STATUS="cannot snapshot the start tree"; return 0; }
    if (
        cd "$GRADE" &&
            export GIT_INDEX_FILE="$WORK/agent.index" &&
            git_ --git-dir="$repo" --work-tree=. read-tree HEAD &&
            git_ --git-dir="$repo" --work-tree=. add -A &&
            git_ --git-dir="$repo" --work-tree=. diff --cached --binary HEAD -- "${pathspec[@]}" > "$WORK/segment.patch"
    ); then
        PATCH_STATUS="ok"
    else
        PATCH_STATUS="git diff failed"
    fi
}

# Python import-hook files (conftest.py, sitecustomize.py, *.pth, ...) and protected paths come
# from the trusted start tree, never from the agent's tree.
make_gradeable() {
    local name rel
    local -a expr=()
    while IFS= read -r name; do
        [ -n "$name" ] || continue
        [ ${#expr[@]} -eq 0 ] || expr+=(-o)
        expr+=(-name "$name")
    done <<EOF
$ODYSSEY_PROTECTED_NAMES
EOF
    if [ ${#expr[@]} -gt 0 ]; then
        find "$GRADE" -mindepth 1 \( "${expr[@]}" \) -prune -exec rm -rf {} + || { ERROR="removing protected names failed"; return 1; }
        while IFS= read -r rel; do
            mkdir -p "$(dirname "$GRADE/$rel")" && cp -a "$TRUSTED/$rel" "$GRADE/$rel"
        done < <(cd "$TRUSTED" && find . -mindepth 1 \( "${expr[@]}" \) -prune -print)
    fi
    while IFS= read -r rel; do
        [ -n "$rel" ] || continue
        rm -rf "${GRADE:?}/$rel"
        if [ -e "$TRUSTED/$rel" ]; then mkdir -p "$(dirname "$GRADE/$rel")" && cp -a "$TRUSTED/$rel" "$GRADE/$rel"; fi
    done <<EOF
$ODYSSEY_PROTECTED_PATHS
EOF
    chmod -R a+rX "$GRADE" 2>/dev/null || true
}

fetch_grader_key() {
    local answer
    answer="$(ctl_request verifier-creds "$ATLAS_VERIFY_TOKEN" 120 '{}')" \
        || { ERROR="no grader key from the controller: $(printf '%s' "$answer" | head -c 300)"; return 1; }
    CREDS_ISSUED=1
    printf '%s' "$answer" | "$PY" -I -B -c '
import json, sys
answer = json.load(sys.stdin)
creds_path, step_path, builder_path = sys.argv[1:4]
builder = open(builder_path, encoding="utf-8").read()
key, secret = answer["access_key"], answer["secret_key"]
with open(creds_path, "w", encoding="utf-8") as out:
    out.write(builder.rstrip("\n") + "\n\n[verifier]\n"
              + "aws_access_key_id = " + key + "\n"
              + "aws_secret_access_key = " + secret + "\n"
              + "region = us-east-1\n")
with open(step_path, "w", encoding="utf-8") as out:
    json.dump(answer.get("record", {}), out, indent=1, sort_keys=True)
' "$CREDS" "$WORK/atlas-step.json" /shared/agent/credentials \
        || { ERROR="cannot write the grader credentials"; return 1; }
    chmod 600 "$CREDS"
}

run_grader() {
    mkdir -p "$RESULTS"
    (
        cd "$GRADE" &&
            env -u AWS_PROFILE -u AWS_ACCESS_KEY_ID -u AWS_SECRET_ACCESS_KEY -u AWS_SESSION_TOKEN \
                -u PYTHONPATH -u PYTHONHOME -u PYTHONSTARTUP \
                AWS_SHARED_CREDENTIALS_FILE="$CREDS" AWS_CONFIG_FILE=/dev/null \
                ATLAS_VERIFIER_PROFILE=verifier ATLAS_OUT="$RESULTS" ATLAS_LIB="$LIB_DIR" \
                ATLAS_TICKET_DIR="$TICKET_DIR" ATLAS_REPO="$GRADE" ATLAS_PYTHON="$PY" \
                ATLAS_GRADING="$TESTS_DIR/grading.json" PYTHONDONTWRITEBYTECODE=1 \
                timeout -k 10 "$ODYSSEY_RUN_TIMEOUT_SEC" bash "$TICKET_DIR/run.sh"
    ) 2>&1 | tee "$WORK/run.log"
    EXIT_CODE=${PIPESTATUS[0]}
    if [ "$EXIT_CODE" -eq 124 ] || [ "$EXIT_CODE" -eq 137 ]; then
        TIMED_OUT=true
        ERROR="run.sh timed out after ${ODYSSEY_RUN_TIMEOUT_SEC}s"
    fi
}

decide() {
    local verdict
    verdict="$("$PY" -I -B "$LIB_DIR/verdict.py" --results "$RESULTS" --exit "$EXIT_CODE")" \
        || { ERROR="verdict.py failed"; return 1; }
    printf '%s\n' "$verdict" > "$WORK/verdict.json"
    REWARD="$(printf '%s' "$verdict" | "$PY" -I -c 'import json,sys; print(json.load(sys.stdin)["reward"])')"
    if [ "$(printf '%s' "$verdict" | "$PY" -I -c 'import json,sys; print(json.load(sys.stdin)["tampered"])')" = 1 ]; then
        TAMPERED=1
        TAMPER_REASONS+=("$(printf '%s' "$verdict" | "$PY" -I -c 'import json,sys; print(json.load(sys.stdin)["reason"])')")
    fi
    VERDICT_REASON="$(printf '%s' "$verdict" | "$PY" -I -c 'import json,sys; print(json.load(sys.stdin)["reason"])')"
}

publish() {
    mkdir -p "$OUT/grader"
    [ -d "$RESULTS" ] && cp -a "$RESULTS/." "$OUT/grader/" 2>/dev/null
    [ -f "$RESULTS/details.json" ] && cp "$RESULTS/details.json" "$OUT/details.json"
    [ -f "$WORK/run.log" ] && cp "$WORK/run.log" "$OUT/grader/run.log"
    [ -f "$WORK/verdict.json" ] && cp "$WORK/verdict.json" "$OUT/grader/verdict.json"
    [ -f "$WORK/segment.patch" ] && cp "$WORK/segment.patch" "$OUT/segment.patch"
    [ -f "$WORK/atlas-step.json" ] && cp "$WORK/atlas-step.json" "$OUT/atlas-step.json"
    [ -f "$ATLAS_GUARD_LOG" ] && cp "$ATLAS_GUARD_LOG" "$OUT/guard-sweeps.jsonl"
    rm -f "$OUT/grader/"*.tmp 2>/dev/null
    # Harbor (the host user) moves these into the step's archive: a root-owned subdirectory
    # it cannot write would abort the trial.
    chmod -R a+rwX "$OUT/grader" 2>/dev/null
}

write_grade() {
    local reasons
    reasons="$(printf '%s\n' "${TAMPER_REASONS[@]+"${TAMPER_REASONS[@]}"}")"
    ATLAS_G_TICKET="$ODYSSEY_TICKET" ATLAS_G_POSITION="$ODYSSEY_POSITION" ATLAS_G_REWARD="$REWARD" \
    ATLAS_G_EXIT="$EXIT_CODE" ATLAS_G_TIMED_OUT="$TIMED_OUT" ATLAS_G_ERROR="$ERROR" \
    ATLAS_G_TAMPERED="$TAMPERED" ATLAS_G_REASONS="$reasons" ATLAS_G_PATCH="$PATCH_STATUS" \
    ATLAS_G_VERDICT="$VERDICT_REASON" "$PY" -I -B -c '
import json, os
e = os.environ
print(json.dumps({
    "ticket": e["ATLAS_G_TICKET"], "position": int(e["ATLAS_G_POSITION"]), "reward": int(e["ATLAS_G_REWARD"]),
    "exit_code": int(e["ATLAS_G_EXIT"]), "timed_out": e["ATLAS_G_TIMED_OUT"] == "true",
    "error": e["ATLAS_G_ERROR"], "tampered": e["ATLAS_G_TAMPERED"] == "1",
    "tamper_reasons": [r for r in e["ATLAS_G_REASONS"].splitlines() if r],
    "verdict": e["ATLAS_G_VERDICT"], "segment_patch": e["ATLAS_G_PATCH"]}, indent=1))
' > "$OUT/grade.json" 2>/dev/null || printf '{"ticket": "%s", "reward": %s}\n' "$ODYSSEY_TICKET" "$REWARD" > "$OUT/grade.json"
}

main() {
    mkdir -p "$OUT"
    ERROR="grader did not finish"
    write_reward
    ERROR=""

    sweep_processes
    check_planted "before grading"
    rm -rf "$WORK"
    mkdir -p -m 700 "$ATLAS_GRADER_ROOT" "$WORK"
    if [ ! -f "$TICKET_DIR/run.sh" ]; then
        ERROR="ticket run.sh missing from the step's tests"
    elif prepare_trusted && copy_agent_tree; then
        write_segment_patch
        if make_gradeable && fetch_grader_key; then
            run_grader
        fi
    fi
    sweep_processes
    if [ "$CREDS_ISSUED" = 1 ]; then
        ctl_request verifier-done "$ATLAS_VERIFY_TOKEN" 60 '{}' >/dev/null || log "warning: could not revoke the grader key"
    fi
    rm -f "$CREDS"
    if [ -z "$ERROR" ]; then decide || true; fi
    publish
    check_planted "after grading"
    if [ "$TAMPERED" = 1 ]; then REWARD=0; fi
    if [ -n "$ERROR" ]; then REWARD=0; fi
    write_grade
    write_reward
    chmod a+rw "$OUT"/* 2>/dev/null
    log "ticket $ODYSSEY_TICKET: reward $REWARD (exit $EXIT_CODE${ERROR:+, $ERROR}${VERDICT_REASON:+; $VERDICT_REASON})"
    if [ "$TAMPERED" = 1 ]; then log "TAMPERING: ${TAMPER_REASONS[*]}"; fi
}

main "$@"
